#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# GitHub issue #174 ("Task — SMTP custom, URL di redirect e verifica provider
# Apple in Supabase Auth", child della mappa wayfinder #165). Come per Apple e
# Google i valori non segreti stanno fuori dal repo, in un env file dedicato in
# home. L'API key di Resend NON viene mai chiesta né salvata: va incollata
# direttamente da Resend nel dashboard Supabase. Assegnazione diretta: la
# libreria sopra ha già valorizzato ENV_FILE a ".env".
ENV_FILE="$HOME/.mycomicbrain-supabase-auth.env"
BUNDLE_ID="com.saviogiordano.mycomicbrain.mycomicbrain"
SUPABASE_PROJECT_REF="ojfwicezfctlwpouudsa"
SUPABASE_HOST="${SUPABASE_PROJECT_REF}.supabase.co"
SUPABASE_CALLBACK_URL="https://${SUPABASE_HOST}/auth/v1/callback"
SUPABASE_DASHBOARD="https://supabase.com/dashboard/project/${SUPABASE_PROJECT_REF}"
DEEP_LINK_REDIRECT="com.saviogiordano.mycomicbrain://login-callback"
APPLE_ENV_FILE="$HOME/.mycomicbrain-apple-signin.env"
# Il secret OAuth di Apple è un JWT con durata massima di 180 giorni.
APPLE_SECRET_MAX_DAYS=180

touch "$ENV_FILE"
chmod 600 "$ENV_FILE"

# _apple_services_id — il Services ID salvato dalla wizard Apple, se presente.
_apple_services_id() {
  [[ -f "$APPLE_ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^APPLE_SERVICES_ID=" "$APPLE_ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# _add_days YYYY-MM-DD N — data + N giorni (BSD date su macOS, GNU altrove).
_add_days() {
  date -j -v+"$2"d -f %Y-%m-%d "$1" +%Y-%m-%d 2>/dev/null \
    || date -d "$1 + $2 days" +%Y-%m-%d 2>/dev/null \
    || printf '(calcola a mano: %s + %s giorni)' "$1" "$2"
}

banner "Supabase Auth — SMTP Resend, URL, Apple e policy password"

# ── Stage 1: dominio mittente su Resend ─────────────────────────────────────
stage "Resend — account e dominio mittente"
say "Le email di conferma partiranno da Resend: serve un dominio verificato."
open_url "https://resend.com/domains"
step "Accedi o registrati su Resend (il piano gratuito basta: 3.000 email/mese, 100/giorno)."
step "Domains → Add Domain: inserisci il tuo dominio, regione \"Ireland (eu-west-1)\" (la stessa di Supabase)."
ask RESEND_DOMAIN "Dominio aggiunto su Resend (es. tuodominio.it):"
write_env RESEND_DOMAIN "$RESEND_DOMAIN"
step "Copia nel DNS del dominio TUTTI i record che Resend mostra (DKIM, più MX e TXT/SPF sul sottodominio send)."
step "Torna su Resend e premi \"Verify DNS Records\": la propagazione può richiedere da pochi minuti ad alcune ore."
pause "Premi Invio quando il dominio risulta \"Verified\" su Resend (se serve tempo, Ctrl-C e rilancia più tardi)."

# ── Stage 2: API key Resend → SMTP Supabase ─────────────────────────────────
stage "SMTP custom in Supabase Auth"
ask SMTP_SENDER_EMAIL "Indirizzo mittente [noreply@${RESEND_DOMAIN}] (Invio = proposto):"
[[ -z "$SMTP_SENDER_EMAIL" ]] && SMTP_SENDER_EMAIL="noreply@${RESEND_DOMAIN}"
write_env SMTP_SENDER_EMAIL "$SMTP_SENDER_EMAIL"
open_url "https://resend.com/api-keys"
step "Create API Key: nome \"supabase-auth\", permesso \"Sending access\", dominio $RESEND_DOMAIN."
step "Copia la chiave (Resend la mostra una volta sola). NON incollarla qui: va solo su Supabase."
pause "Premi Invio quando hai la chiave negli appunti."
open_url "${SUPABASE_DASHBOARD}/auth/smtp"
step "Attiva \"Enable Custom SMTP\" e compila:"
say "    Sender email:  $SMTP_SENDER_EMAIL"
say "    Sender name:   MyComicBrain"
say "    Host:          smtp.resend.com"
say "    Port number:   465"
say "    Username:      resend"
say "    Password:      la API key appena copiata"
step "Save."
pause "Premi Invio quando le impostazioni SMTP risultano salvate."

# ── Stage 3: rate limit email ───────────────────────────────────────────────
stage "Rate limit delle email"
say "Con l'SMTP custom il limite non è più 2 email/ora: lo imposti tu."
open_url "${SUPABASE_DASHBOARD}/auth/rate-limits"
step "\"Rate limit for sending emails\": impostalo ad almeno 30 email/ora (100 è il tetto giornaliero di Resend free)."
ask SUPABASE_EMAIL_RATE_LIMIT "Valore impostato (email/ora):"
write_env SUPABASE_EMAIL_RATE_LIMIT "$SUPABASE_EMAIL_RATE_LIMIT"
step "Save."
pause "Premi Invio quando il rate limit risulta salvato."

# ── Stage 4: Site URL e Redirect URLs ───────────────────────────────────────
stage "URL Configuration"
say "Già impostati durante #171: qui si verifica soltanto."
open_url "${SUPABASE_DASHBOARD}/auth/url-configuration"
step "Site URL deve essere:              $DEEP_LINK_REDIRECT"
step "Redirect URLs deve contenere:      $DEEP_LINK_REDIRECT"
step "Non devono restare localhost:3000 o URL di prova."
if confirm "Site URL e Redirect URLs sono corretti?"; then
  write_env SUPABASE_URLS_VERIFIED "si"
else
  write_env SUPABASE_URLS_VERIFIED "no"
  SKIPPED+=("URL Configuration su Supabase da correggere ($DEEP_LINK_REDIRECT)")
fi

# ── Stage 5: provider Apple (Supabase + Return URL sul portale Apple) ───────
stage "Provider Apple — Client IDs e Return URL"
SERVICES_ID="$(_apple_services_id || true)"
if [[ -z "$SERVICES_ID" ]]; then
  ask SERVICES_ID "Services ID di Apple (non trovato in $APPLE_ENV_FILE):"
fi
open_url "${SUPABASE_DASHBOARD}/auth/providers"
step "Apri \"Apple\": Client IDs deve essere, in quest'ordine (Services ID PRIMO):"
say "    ${SERVICES_ID},${BUNDLE_ID}"
step "Verifica che la Callback URL mostrata sia $SUPABASE_CALLBACK_URL."
pause "Premi Invio quando hai verificato (e se serve corretto e salvato) il provider Apple."
open_url "https://developer.apple.com/account/resources/identifiers/list/serviceId"
step "Apri il Services ID $SERVICES_ID → \"Sign In with Apple\" → Configure."
step "Domains and Subdomains deve contenere:  $SUPABASE_HOST"
step "Return URLs deve contenere:             $SUPABASE_CALLBACK_URL"
step "Se hai cambiato qualcosa: Next → Done → Continue → Save."
if confirm "Domains e Return URL del Services ID sono corretti?"; then
  write_env APPLE_RETURN_URL_VERIFIED "si"
else
  write_env APPLE_RETURN_URL_VERIFIED "no"
  SKIPPED+=("Return URL del Services ID Apple da correggere ($SUPABASE_CALLBACK_URL)")
fi

# ── Stage 6: scadenza del secret OAuth Apple ────────────────────────────────
stage "Secret OAuth di Apple — scadenza"
say "Il campo \"Secret Key (for OAuth)\" del provider Apple su Supabase è un JWT firmato"
say "con la chiave .p8: dura al massimo ${APPLE_SECRET_MAX_DAYS} giorni. Quando scade si rompe"
say "il login Apple via browser (Android); il login nativo su iOS non lo usa."
note "Se non ricordi quando l'hai generato, rigeneralo ora con lo strumento della guida"
note "Supabase \"Login with Apple\" (Team ID, Key ID, Services ID e .p8 da $APPLE_ENV_FILE),"
note "incollalo nel provider Apple su Supabase, salva e usa la data di oggi."
ask APPLE_OAUTH_SECRET_GENERATED_ON "Data di generazione del secret (YYYY-MM-DD):"
write_env APPLE_OAUTH_SECRET_GENERATED_ON "$APPLE_OAUTH_SECRET_GENERATED_ON"
APPLE_OAUTH_SECRET_EXPIRES_ON="$(_add_days "$APPLE_OAUTH_SECRET_GENERATED_ON" "$APPLE_SECRET_MAX_DAYS")"
write_env APPLE_OAUTH_SECRET_EXPIRES_ON "$APPLE_OAUTH_SECRET_EXPIRES_ON"
say "Scadenza calcolata: $APPLE_OAUTH_SECRET_EXPIRES_ON (il promemoria lo crea l'agente su GitHub)."
pause

# ── Stage 7: policy password e test end-to-end ──────────────────────────────
stage "Policy password e prova di registrazione"
open_url "${SUPABASE_DASHBOARD}/auth/providers"
step "Provider \"Email\": Minimum password length = 8,"
step "Password Requirements = \"Lowercase, uppercase letters and digits\" (l'app la impone già lato client)."
if confirm "La policy password remota coincide?"; then
  write_env SUPABASE_PASSWORD_POLICY_VERIFIED "si"
else
  write_env SUPABASE_PASSWORD_POLICY_VERIFIED "no"
  SKIPPED+=("policy password su Supabase da allineare (min 8, lower/upper/digits)")
fi
say ""
say "Ora la prova vera, dall'app:"
step "Registrati con un indirizzo che NON sia un membro del team Supabase."
step "Controlla che l'email arrivi da $SMTP_SENDER_EMAIL (anche in Resend → Emails risulta \"Delivered\")."
step "Tocca il link di conferma sul telefono: deve riaprire l'app e completare l'accesso."
if confirm "Email arrivata e link che riapre l'app?"; then
  write_env SIGNUP_EMAIL_TEST "ok"
else
  write_env SIGNUP_EMAIL_TEST "ko"
  SKIPPED+=("prova di registrazione email non riuscita: controlla Resend → Emails/Logs e Supabase → Logs → Auth")
fi

finish

# ── Riepilogo per il commento di chiusura su GitHub (#174) ────────────────
printf '%s%s  Riepilogo per il ticket GitHub #174%s\n\n' "$BOLD" "$BLUE" "$RESET"
say "Nessun segreto: incollalo in chat o come commento su #174."
printf '\n---\n'
printf 'Dominio Resend: %s\n' "$(_existing RESEND_DOMAIN || echo '(mancante)')"
printf 'Mittente: %s\n' "$(_existing SMTP_SENDER_EMAIL || echo '(mancante)')"
printf 'Rate limit email/ora: %s\n' "$(_existing SUPABASE_EMAIL_RATE_LIMIT || echo '(mancante)')"
printf 'URL Configuration verificata: %s\n' "$(_existing SUPABASE_URLS_VERIFIED || echo '(mancante)')"
printf 'Return URL Services ID verificata: %s\n' "$(_existing APPLE_RETURN_URL_VERIFIED || echo '(mancante)')"
printf 'Secret OAuth Apple generato il: %s\n' "$(_existing APPLE_OAUTH_SECRET_GENERATED_ON || echo '(mancante)')"
printf 'Secret OAuth Apple scade il: %s\n' "$(_existing APPLE_OAUTH_SECRET_EXPIRES_ON || echo '(mancante)')"
printf 'Policy password verificata: %s\n' "$(_existing SUPABASE_PASSWORD_POLICY_VERIFIED || echo '(mancante)')"
printf 'Prova registrazione email: %s\n' "$(_existing SIGNUP_EMAIL_TEST || echo '(mancante)')"
printf -- '---\n\n'
